mapper.select:
SELECT interaction_id,thread_id,turn_id,tool_call_id,plan_revision_id,run_id,operation_key,
questions_json,status,answers_json,revision,created_at_ms,updated_at_ms
FROM ja_interaction_request WHERE thread_id=#{threadId} AND interaction_id=#{interactionId}

mapper.update:
UPDATE ja_interaction_request SET answers_json=#{answersJson},status=#{status},revision=revision+1,
operation_key=#{operationKey},updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE thread_id=#{threadId} AND interaction_id=#{interactionId} AND status='PENDING' AND revision=#{expectedInteractionRevision}

UPDATE ja_interaction_request SET status=#{status},revision=revision+1,operation_key=#{operationKey},
updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE thread_id=#{threadId} AND interaction_id=#{interactionId} AND status='PENDING' AND revision=#{expectedInteractionRevision}

mapper.select:
SELECT event_sequence,thread_id,interaction_id,interaction_revision,kind,occurred_at_ms
FROM ja_interaction_event WHERE thread_id=#{threadId} AND event_sequence>#{afterSequence}
ORDER BY event_sequence ASC
